const toggle=document.querySelector('.menu-toggle');
const nav=document.querySelector('#navigation');
toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&toggle?.getAttribute('aria-expanded')==='true'){toggle.setAttribute('aria-expanded','false');nav.classList.remove('open');toggle.focus()}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});document.querySelectorAll('[data-category]').forEach(card=>card.hidden=button.dataset.filter!=='all'&&card.dataset.category!==button.dataset.filter)}));
document.querySelector('#enquiry')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form),en=form.dataset.lang==='en';const subject=(en?'Project enquiry: ':'项目咨询：')+(d.get('company')||d.get('name'));const body=(en?'Name: ':'称呼：')+d.get('name')+'\n'+(en?'Company / brand: ':'公司 / 品牌：')+d.get('company')+'\nEmail: '+d.get('email')+'\n\n'+d.get('message');window.location.href='mailto:'+form.dataset.email+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);document.querySelector('#form-status').textContent=en?'Your email app has been requested. If it does not open, email us directly at '+form.dataset.email+'. Your enquiry has not been sent automatically.':'已尝试打开邮箱应用。如未打开，请直接发邮件至 '+form.dataset.email+'。咨询内容尚未自动发送。';});
